const assert=require("node:assert/strict");
const {chromium}=require("playwright");
(async()=>{
 const browser=await chromium.launch({headless:true,args:["--no-sandbox"]});
 const page=await browser.newPage({viewport:{width:390,height:844}});
 const errors=[];page.on("pageerror",e=>errors.push(e.message));
 try{
  const response=await page.goto("http://127.0.0.1:3000/topik-mocks",{waitUntil:"domcontentloaded"});
  assert.equal(response.status(),200);
  await page.getByRole("heading",{name:/meet the exam/i}).waitFor();
  assert.equal(await page.getByRole("button",{name:/TOPIK I · Beginner/i}).count(),1);
  assert.equal(await page.getByRole("button",{name:/60th TOPIK I/i}).count(),1);
  for(const n of ["102nd","96th","91st","83rd","64th"])assert.equal(await page.getByRole("button",{name:new RegExp(n+" TOPIK I","i")}).count(),1);
  await page.getByRole("button",{name:/102nd TOPIK I/i}).click();
  assert.equal(await page.getByRole("link",{name:/Listening PDF/i}).count(),1);
  assert.equal(await page.getByRole("link",{name:/Listening MP3 · unverified/i}).count(),1);
  assert.equal(await page.getByRole("link",{name:/reading key · not audited/i}).count(),1);
  await page.getByRole("button",{name:/All papers/i}).click();
  await page.getByRole("button",{name:/60th TOPIK I/i}).click();
  await page.getByRole("button",{name:"Start timer"}).click();
  await page.getByRole("button",{name:"Listening question 1 option 2"}).click();
  await page.getByRole("tab",{name:/Reading 40/i}).click();
  await page.getByRole("button",{name:"Reading question 1 option 3"}).click();
  await page.reload({waitUntil:"domcontentloaded"});
  await page.getByRole("tab",{name:/Reading 40/i}).waitFor();
  assert.equal(await page.getByRole("button",{name:"Reading question 1 option 3"}).getAttribute("aria-pressed"),"true");
  await page.getByRole("button",{name:"Pause"}).click();
  await page.getByRole("button",{name:"Finish mock"}).click();
  await page.getByRole("button",{name:"Confirm submission"}).click();
  await page.getByText(/practice submitted/i).waitFor();
  await page.getByRole("button",{name:/All papers/i}).click();
  await page.getByRole("button",{name:/TOPIK II · Intermediate/i}).click();
  await page.getByRole("button",{name:/60th TOPIK II/i}).click();
  await page.getByRole("tab",{name:/Writing 4/i}).click();
  await page.getByRole("textbox",{name:/Writing answer 51/i}).fill("저는 한국어를 공부합니다.");
  await page.reload({waitUntil:"domcontentloaded"});
  assert.equal(await page.getByRole("textbox",{name:/Writing answer 51/i}).inputValue(),"저는 한국어를 공부합니다.");
  const bounds=await page.evaluate(()=>({scroll:document.documentElement.scrollWidth,width:document.documentElement.clientWidth}));
  assert.ok(bounds.scroll<=bounds.width+2,"TOPIK mobile horizontal overflow "+JSON.stringify(bounds));
  assert.deepEqual(errors,[]);
  console.log("PASS: 19 TOPIK practice sheets (12 I + 7 II), source labels, answer persistence, writing and mobile");
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
